function area(width, height) {
  return width * height;
}
console.log(area(3, 4));

function multiply(a, b = 1) {
  return a * b;
}
console.log(multiply(5), multiply(5, 2));

let name = "global";
function show() {
  let name = "local";
  return name;
}
console.log(show(), name);

const double = function (n) { return n * 2; };
const copy = double;
console.log(copy(4), typeof copy);

const add = (a, b) => a + b;
const half = n => n / 2;
const hi = () => "Hi!";
console.log(add(2, 3), half(8), hi());

function factorial(n) {
  if (n === 1) return 1;
  return n * factorial(n - 1);
}
console.log(factorial(5));

let n = 0;
const id = setInterval(() => {
  n++;
  console.log("tick " + n);
  if (n === 2) clearInterval(id);
}, 100);
console.log("start");

function beep() { console.log("beep"); }
function runTwice(fn) { fn(); fn(); }
runTwice(beep());
